head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16405";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — editAvailYn, count

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(String((dma_pageContext.get("comNm") ?? ""))); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_editAvailYn", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_eduForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16405.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_68_onclick
 * @description img_68 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_68_onclick = function(e){
    try {
        history.back()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16405.img_68_onclick' }); }
};

/**
 * @method
 * @name img_70_onclick
 * @description img_70 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16405.img_70_onclick' }); }
};

/**
 * @method
 * @name img_73_onclick
 * @description img_73 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_73_onclick = async function(e){
    try {
        await scwin.register('Y')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16405.img_73_onclick' }); }
};

/**
 * @method
 * @name img_75_onclick
 * @description img_75 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_75_onclick = function(e){
    try {
        scwin.reset()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16405.img_75_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/support/eduChrg.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/support/eduChrg.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/support/eduChrg.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.reset = function () {
    const frm = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_RegisterReq').reset();
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {void}
 * @hidden N
 */
scwin.print = async function () {
    await $c.win.print();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (_submitYn) {
    const frm = (document.eduForm || { elements: [] });
    if ($c.util.getComponent('dma_RegisterReq').get('disclsEduApplSeq') === '73') {
        const count = (String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))));
        if (parseInt(count) >= 250) {
            await $c.win.alert("교육수용인원이 초과되어 접수를 마감하였습니다.\n다음차수에 신청하여 주시기 바랍니다. 감사합니다.");
            return;
        }
    }
    if (!await scwin.chk()) {
        return;
    }
    await $c.win.alert("교육신청이 완료되었습니다.");
    frm.action = 'eduChrg.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerChargeEducation');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_submitYn) {
    if (!await scwin.chk()) {
        return;
    }
    const frm = (document.eduForm || { elements: [] });
    frm.action = 'eduChrg.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'modifyChrgEducation');
    await scwin.tx_fn_Modify();
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @param {*} _disclsEduApplSeq _disclsEduApplSeq
 * @param {*} _disclsChrgSeq _disclsChrgSeq
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _disclsChrgSeq, _submitYn) {
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        const eduForm = (document.eduForm || { elements: [] });
        $c.util.getComponent('dma_RegisterReq').set('disclsEduApplSeq', _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('disclsChrgSeq', _disclsChrgSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        scwin.form_eduForm.action = 'eduChrg.do';
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeChargeEducation');
        await scwin.tx_fn_Delete();
    } else {
        return;
    }
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk = async function () {
    const frm = (document.eduForm || { elements: [] });
    if (($c.util.getComponent('ipt_chrgNm').getValue() == null ? '' : String($c.util.getComponent('ipt_chrgNm').getValue())) === '' || $c.util.getComponent('ipt_chrgNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("성명을 입력해 주세요");
        $c.util.getComponent("ipt_chrgNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_depNm').getValue() == null ? '' : String($c.util.getComponent('ipt_depNm').getValue())) === '' || $c.util.getComponent('ipt_depNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("소속 부서를 입력해 주세요");
        $c.util.getComponent("ipt_depNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_jobtitlNm').getValue() == null ? '' : String($c.util.getComponent('ipt_jobtitlNm').getValue())) === '' || $c.util.getComponent('ipt_jobtitlNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("직위를 입력해 주세요");
        $c.util.getComponent("ipt_jobtitlNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_cellphoneNo').getValue() == null ? '' : String($c.util.getComponent('ipt_cellphoneNo').getValue())) === '' || $c.util.getComponent('ipt_cellphoneNo').getValue().indexOf(" ") === "") {
        await $c.win.alert("휴대폰 번호를 입력해 주세요");
        $c.util.getComponent("ipt_cellphoneNo").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_email').getValue() == null ? '' : String($c.util.getComponent('ipt_email').getValue())) === '' || $c.util.getComponent('ipt_email').getValue().indexOf(" ") === "") {
        await $c.win.alert("이메일을 입력해 주세요");
        $c.util.getComponent("ipt_email").focus();
        return false;
    }
    return true;
};
